package com.example.starter.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.time.Clock;

/**
 * 统一时钟配置；业务一律使用 UTC，测试可替换为固定时钟。
 */
@Configuration
public class ClockConfig {

    @Bean
    public Clock systemClock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.model;

import java.time.Instant;

/**
 * 削峰邀约。
 *
 * @param id               邀约 ID
 * @param periodStart      时段起点（UTC，含）
 * @param periodEnd        时段终点（UTC，不含）
 * @param rateFenPerKwh    每 kWh 奖励（分）
 * @param createdAt        创建时间（UTC）
 */
public record Invitation(
        Long id,
        Instant periodStart,
        Instant periodEnd,
        int rateFenPerKwh,
        Instant createdAt
) {
}

package com.example.starter.model;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 用户削峰承诺；每个用户每个邀约最多一条有效承诺。
 *
 * @param id            承诺 ID
 * @param invitationId  邀约 ID
 * @param userId        用户 ID
 * @param reductionKwh  承诺减少电量（kWh，0 &lt; 值 &le; 50）
 * @param requestId     承诺幂等 requestId
 * @param createdAt     创建时间（UTC）
 */
public record Commitment(
        Long id,
        Long invitationId,
        String userId,
        BigDecimal reductionKwh,
        String requestId,
        Instant createdAt
) {
}

