package com.example.starter.web;

/**
 * 业务可处理异常；mapped 为建议返回的 HTTP 状态码（409/422 等）。
 */
public class ApiException extends RuntimeException {

    private final int status;

    public ApiException(int status, String message) {
        super(message);
        this.status = status;
    }

    public int getStatus() {
        return status;
    }

    public static ApiException conflict(String message) {
        return new ApiException(409, message);
    }

    public static ApiException unprocessable(String message) {
        return new ApiException(422, message);
    }
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 创建削峰邀约请求；时间为 UTC 左闭右开。
 *
 * @param periodStart   时段起点（含）
 * @param periodEnd     时段终点（不含）
 * @param rateFenPerKwh 每 kWh 奖励（分）；为空取默认 80
 */
public record InvitationRequest(
        @NotNull Instant periodStart,
        @NotNull Instant periodEnd,
        Integer rateFenPerKwh
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 用户承诺请求；承诺量单位 kWh，上限 50。
 *
 * @param userId       用户 ID
 * @param reductionKwh 承诺减少电量（kWh）
 * @param requestId    承诺幂等 requestId
 */
public record CommitmentRequest(
        @NotBlank String userId,
        @NotNull @DecimalMin(value = "0.0001", message = "承诺电量必须大于 0")
        @DecimalMax(value = "50", message = "承诺电量不得超过 50 kWh")
        BigDecimal reductionKwh,
        @NotBlank String requestId
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 计量读数提交请求；基线与实际读数作为同一版本一起提交。
 *
 * @param userId       用户 ID
 * @param baselineKwh  基线电量（kWh）
 * @param actualKwh    实际电量（kWh）
 * @param periodStart  读数时段起点（UTC，含）
 * @param periodEnd    读数时段终点（UTC，不含）
 * @param reason       更正缘由；首版留空，更正时必填
 */
public record ReadingRequest(
        @NotBlank String userId,
        @NotNull BigDecimal baselineKwh,
        @NotNull BigDecimal actualKwh,
        @NotNull Instant periodStart,
        @NotNull Instant periodEnd,
        String reason
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 结算请求；requestId 与承诺各自独立。
 *
 * @param userId    用户 ID
 * @param requestId 结算幂等 requestId
 */
public record SettlementRequest(
        @NotBlank String userId,
        @NotBlank String requestId
) {
}

