            String userId = "u-race-" + round + "-" + seq.incrementAndGet();
            long invitationId = prepareChain(userId, "30", "23");

            ExecutorService pool = Executors.newFixedThreadPool(2);
            CyclicBarrier barrier = new CyclicBarrier(2);
            try {
                Future<?> settleFuture = pool.submit(() -> {
                    barrier.await();
                    service.settle(invitationId, new SettlementRequest(userId, "settle-" + round));
                    return null;
                });
                Future<?> correctFuture = pool.submit(() -> {
                    barrier.await();
                    service.submitReading(invitationId, reading(userId, "30", "25", "竞争更正" + round));
                    return null;
                });
                settleFuture.get(30, TimeUnit.SECONDS);
                correctFuture.get(30, TimeUnit.SECONDS);
            } finally {
                pool.shutdownNow();
            }

