        String day = "2026-09-2" + Math.min(1 + seq.incrementAndGet() % 8, 8);
        Instant start = Instant.parse(day + "T18:00:00Z");
        Instant end = Instant.parse(day + "T19:00:00Z");
        long invitationId = service.createInvitation(new InvitationRequest(start, end, 80)).id();
        service.createCommitment(invitationId,
